<?php
require_once dirname(__DIR__).'/config/database.php';require_once dirname(__DIR__).'/includes/layout.php';require_login('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);if($id&&(int)$id!==(int)current_user()['id']){$pdo->prepare("UPDATE users SET is_active=IF(is_active=1,0,1) WHERE id=? AND role='student'")->execute([$id]);flash('Student access status updated.');}redirect('admin/students.php');}
$search=trim($_GET['q']??'');$sql="SELECT u.id,u.full_name,u.email,u.phone,u.is_active,u.created_at,COUNT(DISTINCT e.id) AS enrollments FROM users u LEFT JOIN enrollments e ON e.user_id=u.id WHERE u.role='student'";$params=[];if($search!==''){$sql.=' AND (u.full_name LIKE ? OR u.email LIKE ?)';$params=['%'.$search.'%','%'.$search.'%'];}$sql.=' GROUP BY u.id ORDER BY u.created_at DESC';$q=$pdo->prepare($sql);$q->execute($params);$students=$q->fetchAll();start_page('Manage students','students'); ?>
<div class="mb-4 flex flex-wrap items-center justify-between gap-3"><p class="muted">Student accounts and course activity.</p><form class="flex gap-2"><input class="field !w-60" name="q" placeholder="Search name or email" value="<?= e($search) ?>"><button class="btn-secondary">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Contact</th><th>Courses</th><th>Joined</th><th>Access</th><th>Action</th></tr></thead><tbody><?php foreach($students as $s): ?><tr><td class="font-semibold"><?= e($s['full_name']) ?></td><td><?= e($s['email']) ?><div class="text-xs text-slate-400"><?= e($s['phone']??'') ?></div></td><td><?= (int)$s['enrollments'] ?></td><td><?= e(date('M j, Y',strtotime($s['created_at']))) ?></td><td><span class="badge badge-<?= $s['is_active']?'success':'failed' ?>"><?= $s['is_active']?'active':'suspended' ?></span></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$s['id'] ?>"><button class="<?= $s['is_active']?'btn-danger':'btn-secondary' ?>"><?= $s['is_active']?'Suspend':'Restore' ?></button></form></td></tr><?php endforeach ?><?php if(!$students): ?><tr><td colspan="6" class="py-8 text-center text-slate-500">No matching students.</td></tr><?php endif ?></tbody></table></div><?php end_page(); ?>
